def link_charges(apps, schema_editor):
    """Charges recorded before (a 100 taken out of the owner's own money, noted "CIC charges ...") belong to the money
    taken out the same day: link each one to it, and mark that withdrawal instant."""
    Movement = apps.get_model("accounting", "InvestmentMovement")
    charges = Movement.objects.filter(kind="WITHDRAWAL", reversed_at__isnull=True, note__istartswith="CIC charges", charge_of__isnull=True)
    linked = set()
    for charge in charges.order_by("occurred_on", "pk"):
        withdrawal = (Movement.objects.filter(investment_id=charge.investment_id, organization_id=charge.organization_id, kind="WITHDRAWAL",
                                              occurred_on=charge.occurred_on, reversed_at__isnull=True, charge_of__isnull=True)
                      .exclude(pk=charge.pk).exclude(note__istartswith="CIC charges").exclude(idempotency_key__startswith="business-money-in:")
                      .exclude(pk__in=linked).order_by("pk").first())
        if withdrawal:
            linked.add(withdrawal.pk)
            Movement.objects.filter(pk=charge.pk).update(charge_of=withdrawal)
            Movement.objects.filter(pk=withdrawal.pk).update(speed="INSTANT")


